mkdir -p /work/repo/.railway && cat > /work/repo/.railway/railway.ts <<'EOF'
// Railway Infrastructure as Code for this Healthchecks deployment.
//
// Preview:  cd .railway && npm ci && cd .. && railway config plan
// Apply:    railway config apply
//
// See docs/deploy-railway.md for the full first-time setup, including the
// secrets that must be set by hand (they are never stored in this file).
import { defineRailway, github, postgres, preserve, project, service } from "railway/iac";

// The public hostname users will visit. Railway serves it over HTTPS with an
// automatically issued certificate once the DNS records it asks for exist.
const DOMAIN: string = "hc.example.com";

// GitHub repository and branch Railway builds and auto-deploys from.
const REPO = "albertogrande/healthchecks";
const BRANCH = "master";

// uWSGI in docker/uwsgi.ini listens on this port.
const PORT = "8000";

export default defineRailway(() => {
  if (DOMAIN === "hc.example.com") {
    throw new Error("Set DOMAIN in .railway/railway.ts to your real hostname before planning.");
  }

  const db = postgres("postgres");

  const web = service("healthchecks", {
    source: github(REPO, { branch: BRANCH }),
    build: {
      builder: "DOCKERFILE",
      dockerfilePath: "docker/Dockerfile",
    },
    // Wraps the image's uWSGI command with a check that the required secrets
    // are present, so a misconfigured deploy fails instead of running insecurely.
    start: "/opt/healthchecks/docker/railway-start.sh",
    // Checked on every deploy; traffic only switches once it returns 200.
    // /api/v3/status/ also verifies the database connection. Migrations run
    // before uWSGI starts serving, so allow time for them.
    healthcheck: "/api/v3/status/",
    healthcheckTimeout: 300,
    deploy: {
      // Restart the container whenever it exits. Inside the container the
      // uWSGI master also respawns crashed workers and the sendalerts /
      // sendreports daemons.
      restartPolicyType: "ALWAYS",
      // Keep one replica: every replica runs its own sendalerts and
      // sendreports loop.
      sleepApplication: false,
    },
    replicas: 1,
    domains: [{ domain: DOMAIN, port: Number(PORT) }],
    env: {
      PORT,
      DEBUG: "False",
      SITE_ROOT: `https://${DOMAIN}`,
      // healthcheck.railway.app is the Host header Railway's deploy healthcheck sends.
      ALLOWED_HOSTS: `${DOMAIN},healthcheck.railway.app`,
      // Railway's edge terminates TLS and sets X-Forwarded-Proto.
      SECURE_PROXY_SSL_HEADER: "HTTP_X_FORWARDED_PROTO,https",
      PING_EMAIL_DOMAIN: DOMAIN,
      // Print application errors and tracebacks to stdout so they appear in
      // Railway's log viewer (they are also still stored in the database).
      LOG_TO_STDOUT: "True",

      DB: "postgres",
      DB_HOST: db.env.PGHOST,
      DB_PORT: db.env.PGPORT,
      DB_NAME: db.env.PGDATABASE,
      DB_USER: db.env.PGUSER,
      DB_PASSWORD: db.env.PGPASSWORD,

      DEFAULT_FROM_EMAIL: `healthchecks@${DOMAIN}`,

      // Secrets: set these in Railway (dashboard or `railway variables --set`).
      // preserve() keeps whatever value Railway already holds.
      SECRET_KEY: preserve(),
      EMAIL_HOST: preserve(),
      EMAIL_HOST_USER: preserve(),
      EMAIL_HOST_PASSWORD: preserve(),
    },
  });

  return project("healthchecks", { resources: [db, web] });
});
EOF
