#!/bin/sh
# Start command for the Railway deployment (see .railway/railway.ts).
# Refuses to start with an insecure or missing configuration, then hands
# over to the same uWSGI command the Dockerfile uses.
set -eu

fail() {
    echo "railway-start: $1" >&2
    exit 1
}

if [ -z "${SECRET_KEY_FILE:-}" ]; then
    case "${SECRET_KEY:-}" in
        "" | "---") fail "SECRET_KEY is not set. Set it to a long random value in the Railway service variables." ;;
    esac
fi

case "${SITE_ROOT:-}" in
    https://*) ;;
    *) fail "SITE_ROOT must be an https:// URL (got '${SITE_ROOT:-}')." ;;
esac

if [ -z "${EMAIL_HOST:-}" ]; then
    echo "railway-start: WARNING: EMAIL_HOST is not set; sign-up, login links and email alerts will not be sent." >&2
fi

exec uwsgi /opt/healthchecks/docker/uwsgi.ini
EOF
